-- Migration 18: Token Share Links & Token-Specific Referrals

-- Token share links generated by users to share specific tokens into groups/chats
CREATE TABLE IF NOT EXISTS token_shares (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    code TEXT UNIQUE NOT NULL,
    token_address TEXT NOT NULL,
    referrer_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    CONSTRAINT token_shares_referrer_token_key UNIQUE (referrer_id, token_address)
);

CREATE INDEX IF NOT EXISTS idx_token_shares_code ON token_shares(code);
CREATE INDEX IF NOT EXISTS idx_token_shares_referrer ON token_shares(referrer_id);

-- Token-specific referrals: attributes trades of a specific token to the user who shared the link (5% fee)
CREATE TABLE IF NOT EXISTS token_referrals (
    id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),
    user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token_address TEXT NOT NULL,
    referrer_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    total_fees_earned NUMERIC DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    last_trade_at TIMESTAMPTZ,
    CONSTRAINT token_referrals_user_token_key UNIQUE (user_id, token_address)
);

CREATE INDEX IF NOT EXISTS idx_token_referrals_referrer ON token_referrals(referrer_id);
CREATE INDEX IF NOT EXISTS idx_token_referrals_user_token ON token_referrals(user_id, token_address);
